import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousFileChannel;
import java.nio.channels.CompletionHandler;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.EnumSet;
import java.util.concurrent.CompletableFuture;

public class AsyncFileReader {
    public static CompletableFuture<String> readFileAsync(Path path) {
        CompletableFuture<String> futureResult = new CompletableFuture<>();

        try {
            AsynchronousFileChannel fileChannel = AsynchronousFileChannel.open(
                path, EnumSet.of(StandardOpenOption.READ)
            );

            ByteBuffer buffer = ByteBuffer.allocateDirect(1024);

            fileChannel.read(buffer, 0, buffer, new CompletionHandler<Integer, ByteBuffer>() {
                @Override
                public void completed(Integer result, ByteBuffer attachment) {
                    attachment.flip();
                    byte[] data = new byte[attachment.remaining()];
                    attachment.get(data);
                    futureResult.complete(new String(data));
                    try { fileChannel.close(); } catch (Exception ignored) {}
                }

                @Override
                public void failed(Throwable exc, ByteBuffer attachment) {
                    futureResult.completeExceptionally(exc);
                    try { fileChannel.close(); } catch (Exception ignored) {}
                }
            });
        } catch (Exception e) {
            futureResult.completeExceptionally(e);
        }

        return futureResult;
    }
}
